mutants.old:
do {
  const page = await listUniverses({ lifecycle: "active", cursor });
  universes.push(...page.universes);
  cursor = page.nextCursor ?? undefined;
} while (cursor !== undefined);
return universes;

mutants.new:
try {
  do {
    const page = await listUniverses({ lifecycle: "active", cursor });
    universes.push(...page.universes);
    cursor = page.nextCursor ?? undefined;
  } while (cursor !== undefined);
} catch (cause) {
  if (universes.length === 0) {
    throw cause;
  }
}
return universes;
